const std = @import("std");
const math = std.math;

pub const Error = error{
    InvalidDimension,
};

pub fn rmsnormForward(
    output: []f32,
    input: []const f32,
    weight: []const f32,
    eps: f32,
) Error!void {
    const n = input.len;
    if (n == 0) return;
    if (output.len != n or weight.len != n) return Error.InvalidDimension;

    var sum_sq: f32 = 0.0;
    for (input) |x| {
        sum_sq += x * x;
    }

    const mean_sq = sum_sq / @as(f32, @floatFromInt(n));
    const variance_eps = @max(0.0, mean_sq + eps);
    const inv_std = 1.0 / @sqrt(variance_eps);

    for (input, weight, 0..) |x, w, i| {
        output[i] = x * inv_std * w;
    }
}

pub fn rmsnormBackward(
    grad_input: []f32,
    grad_weight_contrib: []f32,
    grad_output: []const f32,
    input: []const f32,
    weight: []const f32,
    eps: f32,
) Error!void {
    const n = input.len;
    if (n == 0) return;
    if (grad_input.len != n or grad_weight_contrib.len != n or grad_output.len != n or weight.len != n) return Error.InvalidDimension;

    var sum_sq: f32 = 0.0;
    for (input) |x| {
        sum_sq += x * x;
    }

    const mean_sq = sum_sq / @as(f32, @floatFromInt(n));
    const variance_eps = @max(0.0, mean_sq + eps);
    const inv_std = 1.0 / @sqrt(variance_eps);
    const inv_std_pow3 = inv_std * inv_std * inv_std;

    var sum_gwx: f32 = 0.0;
    for (grad_output, weight, input) |g, w, x| {
        sum_gwx += g * w * x;
    }

    const common_term = sum_gwx * inv_std_pow3 / @as(f32, @floatFromInt(n));

    for (grad_output, weight, input, 0..) |g, w, x, i| {
        grad_input[i] = w * inv_std * g - x * common_term;
        grad_weight_contrib[i] = g * x * inv_std;
    }
}

pub fn layernormForward(
    output: []f32,
    input: []const f32,
    weight: []const f32,
    bias: []const f32,
    eps: f32,
) Error!void {
    const n = input.len;
    if (n == 0) return;
    if (output.len != n or weight.len != n or bias.len != n) return Error.InvalidDimension;

    var sum: f32 = 0.0;
    var sum_sq: f32 = 0.0;
    for (input) |x| {
        sum += x;
        sum_sq += x * x;
    }

    const mean = sum / @as(f32, @floatFromInt(n));
    const mean_sq = sum_sq / @as(f32, @floatFromInt(n));
    const variance = @max(0.0, mean_sq - mean * mean);
    const variance_eps = variance + eps;
    const inv_std = 1.0 / @sqrt(variance_eps);

    for (input, weight, bias, 0..) |x, w, b, i| {
        const normalized = (x - mean) * inv_std;
        output[i] = normalized * w + b;
    }
}

pub fn geluForward(output: []f32, input: []const f32) Error!void {
    const n = input.len;
    if (output.len != n) return Error.InvalidDimension;
    const sqrt2_inv: f32 = 0.7071067811865475;
    for (input, 0..) |x, i| {
        const cdf = 0.5 * (1.0 + math.erf(x * sqrt2_inv));
        output[i] = x * cdf;
    }
}

pub fn geluBackward(
    grad_input: []f32,
    grad_output: []const f32,
    input: []const f32,
) Error!void {
    const n = input.len;
    if (grad_input.len != n or grad_output.len != n) return Error.InvalidDimension;
    const sqrt2_inv: f32 = 0.7071067811865475;
    const pi_inv_sqrt2: f32 = 0.3989422804014327;
    for (input, grad_output, 0..) |x, g, i| {
        const cdf = 0.5 * (1.0 + math.erf(x * sqrt2_inv));
        const pdf = math.exp(-0.5 * x * x) * pi_inv_sqrt2;
        const grad = cdf + x * pdf;
        grad_input[i] = g * grad;
    }
}

pub fn softmaxForward(output: []f32, input: []const f32) Error!void {
    const n = input.len;
    if (n == 0) return;
    if (output.len != n) return Error.InvalidDimension;

    var max_val: f32 = input[0];
    for (input[1..]) |x| {
        max_val = @max(max_val, x);
    }

    var sum_exp: f32 = 0.0;
    for (input) |x| {
        sum_exp += math.exp(x - max_val);
    }

    const inv_sum_exp = if (sum_exp == 0.0) 0.0 else 1.0 / sum_exp;

    for (input, 0..) |x, i| {
        output[i] = math.exp(x - max_val) * inv_sum_exp;
    }
}
