inductive ZigError
| InvalidDimension

inductive ZigResult (α : Type)
| ok (val : α)
| err (e : ZigError)

def match_false {α : Type} (b : Bool) (t f : α) (h : b = false) :
  (match b with | true => t | false => f) = f :=
  Eq.ndrec (motive := fun x => (match x with | true => t | false => f) = f) (Eq.refl f) (Eq.symm h)

def match_true {α : Type} (b : Bool) (t f : α) (h : b = true) :
  (match b with | true => t | false => f) = t :=
  Eq.ndrec (motive := fun x => (match x with | true => t | false => f) = t) (Eq.refl t) (Eq.symm h)

def sum_sq_loop : List Real → Real
| [] => 0
| x :: xs => (x * x) + sum_sq_loop xs

def rmsnorm_fwd_loop : List Real → List Real → Real → List Real
| [], _ , _ => []
| _, [], _ => []
| x :: xs, w :: ws, inv_std => (x * inv_std * w) :: rmsnorm_fwd_loop xs ws inv_std

def rmsnorm_spec (input weight : List Real) (eps : Real) : List Real :=
  rmsnorm_fwd_loop input weight (1 / Real.sqrt (Max.max 0 ((sum_sq_loop input / input.length) + eps)))

def rmsnorm_forward_zig_model (input weight : List Real) (eps : Real) : ZigResult (List Real) :=
  match Nat.beq input.length 0 with
  | true => ZigResult.ok []
  | false =>
    match Nat.beq input.length weight.length with
    | false => ZigResult.err ZigError.InvalidDimension
    | true =>
      (fun sum_sq =>
        (fun mean_sq =>
          (fun var_eps =>
            (fun inv_std =>
              ZigResult.ok (rmsnorm_fwd_loop input weight inv_std)
            ) (1 / Real.sqrt var_eps)
          ) (Max.max 0 (mean_sq + eps))
        ) (sum_sq / input.length)
      ) (sum_sq_loop input)

theorem rmsnorm_forward_correct (input weight : List Real) (eps : Real)
  (h_not_empty : Nat.beq input.length 0 = false)
  (h_len : Nat.beq input.length weight.length = true) :
  rmsnorm_forward_zig_model input weight eps = ZigResult.ok (rmsnorm_spec input weight eps) :=
  Eq.trans
    (match_false (Nat.beq input.length 0)
      (ZigResult.ok [])
      (match Nat.beq input.length weight.length with
       | false => ZigResult.err ZigError.InvalidDimension
       | true => ZigResult.ok (rmsnorm_spec input weight eps))
      h_not_empty)
    (match_true (Nat.beq input.length weight.length)
      (ZigResult.ok (rmsnorm_spec input weight eps))
      (ZigResult.err ZigError.InvalidDimension)
      h_len)

def sum_gwx_loop : List Real → List Real → List Real → Real
| [], _, _ => 0
| _, [], _ => 0
| _, _, [] => 0
| g :: gs, w :: ws, x :: xs => (g * w * x) + sum_gwx_loop gs ws xs

def rmsnorm_bwd_loop : List Real → List Real → List Real → Real → Real → List Real × List Real
| [], _, _, _, _ => ([], [])
| _, [], _, _, _ => ([], [])
| _, _, [], _, _ => ([], [])
| g :: gs, w :: ws, x :: xs, inv_std, common_term =>
  (fun rest =>
    ((w * inv_std * g - x * common_term) :: rest.1, (g * x * inv_std) :: rest.2)
  ) (rmsnorm_bwd_loop gs ws xs inv_std common_term)

def rmsnorm_bwd_spec (g_out input weight : List Real) (eps : Real) : List Real × List Real :=
  (fun inv_std =>
    (fun common_term =>
      rmsnorm_bwd_loop g_out weight input inv_std common_term
    ) (sum_gwx_loop g_out weight input * (inv_std * inv_std * inv_std) / input.length)
  ) (1 / Real.sqrt (Max.max 0 ((sum_sq_loop input / input.length) + eps)))

def rmsnorm_backward_zig_model (g_out input weight : List Real) (eps : Real) : ZigResult (List Real × List Real) :=
  match Nat.beq input.length 0 with
  | true => ZigResult.ok ([], [])
  | false =>
    match (Nat.beq g_out.length input.length) && (Nat.beq weight.length input.length) with
    | false => ZigResult.err ZigError.InvalidDimension
    | true =>
      (fun sum_sq =>
        (fun mean_sq =>
          (fun var_eps =>
            (fun inv_std =>
              (fun inv_std_pow3 =>
                (fun sum_gwx =>
                  (fun common_term =>
                    ZigResult.ok (rmsnorm_bwd_loop g_out weight input inv_std common_term)
                  ) (sum_gwx * inv_std_pow3 / input.length)
                ) (sum_gwx_loop g_out weight input)
              ) (inv_std * inv_std * inv_std)
            ) (1 / Real.sqrt var_eps)
          ) (Max.max 0 (mean_sq + eps))
        ) (sum_sq / input.length)
      ) (sum_sq_loop input)

