  (h_not_empty : Nat.beq input.length 0 = false)
  (h_len : ((Nat.beq g_out.length input.length) && (Nat.beq weight.length input.length)) = true) :
  rmsnorm_backward_zig_model g_out input weight eps = ZigResult.ok (rmsnorm_bwd_spec g_out input weight eps) :=
  Eq.trans
    (match_false (Nat.beq input.length 0)
      (ZigResult.ok ([], []))
      (match ((Nat.beq g_out.length input.length) && (Nat.beq weight.length input.length)) with
       | false => ZigResult.err ZigError.InvalidDimension
       | true => ZigResult.ok (rmsnorm_bwd_spec g_out input weight eps))
      h_not_empty)
    (match_true ((Nat.beq g_out.length input.length) && (Nat.beq weight.length input.length))
