      (ZigResult.err ZigError.InvalidDimension)
      h_len)

def sum_loop : List Real → Real
| [] => 0
| x :: xs => x + sum_loop xs

def layernorm_fwd_loop : List Real → List Real → List Real → Real → Real → List Real
| [], _, _, _, _ => []
| _, [], _, _, _ => []
| _, _, [], _, _ => []
| x :: xs, w :: ws, b :: bs, mean, inv_std =>
  ((x - mean) * inv_std * w + b) :: layernorm_fwd_loop xs ws bs mean inv_std

def layernorm_spec (input weight bias : List Real) (eps : Real) : List Real :=
  (fun mean =>
    (fun variance =>
      (fun inv_std =>
        layernorm_fwd_loop input weight bias mean inv_std
      ) (1 / Real.sqrt (variance + eps))
    ) (Max.max 0 ((sum_sq_loop input / input.length) - (mean * mean)))
  ) (sum_loop input / input.length)

def layernorm_forward_zig_model (input weight bias : List Real) (eps : Real) : ZigResult (List Real) :=
  match Nat.beq input.length 0 with
  | true => ZigResult.ok []
  | false =>
    match (Nat.beq weight.length input.length) && (Nat.beq bias.length input.length) with
    | false => ZigResult.err ZigError.InvalidDimension
    | true =>
      (fun sum =>
        (fun sum_sq =>
          (fun mean =>
            (fun mean_sq =>
              (fun variance =>
                (fun var_eps =>
                  (fun inv_std =>
                    ZigResult.ok (layernorm_fwd_loop input weight bias mean inv_std)
                  ) (1 / Real.sqrt var_eps)
                ) (variance + eps)
              ) (Max.max 0 (mean_sq - mean * mean))
            ) (sum_sq / input.length)
          ) (sum / input.length)
        ) (sum_sq_loop input)
      ) (sum_loop input)

