  rmsnorm_forward_zig_model input weight eps = ZigResult.ok (rmsnorm_spec input weight eps) :=
  Eq.trans
    (match_false (Nat.beq input.length 0)
      (ZigResult.ok [])
      (match Nat.beq input.length weight.length with
       | false => ZigResult.err ZigError.InvalidDimension
       | true => ZigResult.ok (rmsnorm_spec input weight eps))
      h_not_empty)
    (match_true (Nat.beq input.length weight.length)
      (ZigResult.ok (rmsnorm_spec input weight eps))
      (ZigResult.err ZigError.InvalidDimension)
      h_len)

def sum_gwx_loop : List Real → List Real → List Real → Real
| [], _, _ => 0
| _, [], _ => 0
| _, _, [] => 0
| g :: gs, w :: ws, x :: xs => (g * w * x) + sum_gwx_loop gs ws xs

def rmsnorm_bwd_loop : List Real → List Real → List Real → Real → Real → List Real × List Real
| [], _, _, _, _ => ([], [])
| _, [], _, _, _ => ([], [])
| _, _, [], _, _ => ([], [])
| g :: gs, w :: ws, x :: xs, inv_std, common_term =>
  (fun rest =>
    ((w * inv_std * g - x * common_term) :: rest.1, (g * x * inv_std) :: rest.2)
  ) (rmsnorm_bwd_loop gs ws xs inv_std common_term)

def rmsnorm_bwd_spec (g_out input weight : List Real) (eps : Real) : List Real × List Real :=
  (fun inv_std =>
    (fun common_term =>
      rmsnorm_bwd_loop g_out weight input inv_std common_term
    ) (sum_gwx_loop g_out weight input * (inv_std * inv_std * inv_std) / input.length)
  ) (1 / Real.sqrt (Max.max 0 ((sum_sq_loop input / input.length) + eps)))

def rmsnorm_backward_zig_model (g_out input weight : List Real) (eps : Real) : ZigResult (List Real × List Real) :=
  match Nat.beq input.length 0 with
  | true => ZigResult.ok ([], [])
  | false =>
    match (Nat.beq g_out.length input.length) && (Nat.beq weight.length input.length) with
    | false => ZigResult.err ZigError.InvalidDimension
    | true =>
      (fun sum_sq =>
        (fun mean_sq =>
          (fun var_eps =>
            (fun inv_std =>
              (fun inv_std_pow3 =>
                (fun sum_gwx =>
                  (fun common_term =>
                    ZigResult.ok (rmsnorm_bwd_loop g_out weight input inv_std common_term)
                  ) (sum_gwx * inv_std_pow3 / input.length)
                ) (sum_gwx_loop g_out weight input)
              ) (inv_std * inv_std * inv_std)
            ) (1 / Real.sqrt var_eps)
          ) (Max.max 0 (mean_sq + eps))
        ) (sum_sq / input.length)
      ) (sum_sq_loop input)

theorem rmsnorm_backward_correct (g_out input weight : List Real) (eps : Real)
  (h_not_empty : Nat.beq input.length 0 = false)
  (h_len : ((Nat.beq g_out.length input.length) && (Nat.beq weight.length input.length)) = true) :
  rmsnorm_backward_zig_model g_out input weight eps = ZigResult.ok (rmsnorm_bwd_spec g_out input weight eps) :=
  Eq.trans
    (match_false (Nat.beq input.length 0)
      (ZigResult.ok ([], []))
      (match ((Nat.beq g_out.length input.length) && (Nat.beq weight.length input.length)) with
       | false => ZigResult.err ZigError.InvalidDimension
       | true => ZigResult.ok (rmsnorm_bwd_spec g_out input weight eps))
      h_not_empty)
    (match_true ((Nat.beq g_out.length input.length) && (Nat.beq weight.length input.length))
      (ZigResult.ok (rmsnorm_bwd_spec g_out input weight eps))
      (ZigResult.err ZigError.InvalidDimension)
      h_len)

def sum_loop : List Real → Real
| [] => 0
| x :: xs => x + sum_loop xs

def layernorm_fwd_loop : List Real → List Real → List Real → Real → Real → List Real
| [], _, _, _, _ => []
| _, [], _, _, _ => []
| _, _, [], _, _ => []
| x :: xs, w :: ws, b :: bs, mean, inv_std =>
  ((x - mean) * inv_std * w + b) :: layernorm_fwd_loop xs ws bs mean inv_std

def layernorm_spec (input weight bias : List Real) (eps : Real) : List Real :=
  (fun mean =>
    (fun variance =>
      (fun inv_std =>
        layernorm_fwd_loop input weight bias mean inv_std
      ) (1 / Real.sqrt (variance + eps))
    ) (Max.max 0 ((sum_sq_loop input / input.length) - (mean * mean)))
  ) (sum_loop input / input.length)

def layernorm_forward_zig_model (input weight bias : List Real) (eps : Real) : ZigResult (List Real) :=
  match Nat.beq input.length 0 with
  | true => ZigResult.ok []
  | false =>
    match (Nat.beq weight.length input.length) && (Nat.beq bias.length input.length) with
    | false => ZigResult.err ZigError.InvalidDimension
    | true =>
      (fun sum =>
        (fun sum_sq =>
          (fun mean =>
            (fun mean_sq =>
              (fun variance =>
                (fun var_eps =>
                  (fun inv_std =>
                    ZigResult.ok (layernorm_fwd_loop input weight bias mean inv_std)
                  ) (1 / Real.sqrt var_eps)
                ) (variance + eps)
              ) (Max.max 0 (mean_sq - mean * mean))
            ) (sum_sq / input.length)
          ) (sum / input.length)
        ) (sum_sq_loop input)
      ) (sum_loop input)

theorem layernorm_forward_correct (input weight bias : List Real) (eps : Real)
  (h_not_empty : Nat.beq input.length 0 = false)
  (h_len : ((Nat.beq weight.length input.length) && (Nat.beq bias.length input.length)) = true) :
  layernorm_forward_zig_model input weight bias eps = ZigResult.ok (layernorm_spec input weight bias eps) :=
  Eq.trans
    (match_false (Nat.beq input.length 0)
      (ZigResult.ok [])
      (match ((Nat.beq weight.length input.length) && (Nat.beq bias.length input.length)) with
       | false => ZigResult.err ZigError.InvalidDimension
       | true => ZigResult.ok (layernorm_spec input weight bias eps))
      h_not_empty)
    (match_true ((Nat.beq weight.length input.length) && (Nat.beq bias.length input.length))
      (ZigResult.ok (layernorm_spec input weight bias eps))
      (ZigResult.err ZigError.InvalidDimension)
      h_len)

def gelu_fwd_loop : List Real → List Real
| [] => []
| x :: xs =>
  (fun cdf =>
    (x * cdf) :: gelu_fwd_loop xs
  ) (1/2 * (1 + Real.erf (x * (1 / Real.sqrt 2))))

def gelu_spec (input : List Real) : List Real :=
  gelu_fwd_loop input

def gelu_forward_zig_model (input : List Real) : ZigResult (List Real) :=
  ZigResult.ok (gelu_fwd_loop input)

theorem gelu_forward_correct (input : List Real) :
  gelu_forward_zig_model input = ZigResult.ok (gelu_spec input) :=
  Eq.refl (ZigResult.ok (gelu_spec input))

def gelu_bwd_loop : List Real → List Real → List Real
| [], _ => []
| _, [] => []
| x :: xs, g :: gs =>
  (fun cdf =>
    (fun pdf =>
      (fun grad =>
        (g * grad) :: gelu_bwd_loop xs gs
      ) (cdf + x * pdf)
    ) (Real.exp (-1/2 * x * x) * (1 / Real.sqrt (2 * Real.pi)))
  ) (1/2 * (1 + Real.erf (x * (1 / Real.sqrt 2))))

def gelu_bwd_spec (input g_out : List Real) : List Real :=
  gelu_bwd_loop input g_out

def gelu_backward_zig_model (input g_out : List Real) : ZigResult (List Real) :=
  match Nat.beq g_out.length input.length with
  | false => ZigResult.err ZigError.InvalidDimension
  | true => ZigResult.ok (gelu_bwd_loop input g_out)

theorem gelu_backward_correct (input g_out : List Real)
  (h_len : Nat.beq g_out.length input.length = true) :
  gelu_backward_zig_model input g_out = ZigResult.ok (gelu_bwd_spec input g_out) :=
  match_true (Nat.beq g_out.length input.length)
    (ZigResult.ok (gelu_bwd_spec input g_out))
    (ZigResult.err ZigError.InvalidDimension)
    h_len

def max_loop : List Real → Real → Real
| [], m => m
| x :: xs, m => max_loop xs (Max.max m x)

def list_max (l : List Real) : Real :=
  match l with
  | [] => 0
  | x :: xs => max_loop xs x

def sum_exp_loop : List Real → Real → Real
| [], _ => 0
| x :: xs, m => Real.exp (x - m) + sum_exp_loop xs m

def softmax_fwd_loop : List Real → Real → Real → List Real
| [], _, _ => []
| x :: xs, m, inv_sum => (Real.exp (x - m) * inv_sum) :: softmax_fwd_loop xs m inv_sum

def softmax_spec (input : List Real) : List Real :=
  (fun m =>
    (fun sum_exp =>
      (fun inv_sum =>
        softmax_fwd_loop input m inv_sum
      ) (1 / sum_exp)
    ) (sum_exp_loop input m)
  ) (list_max input)

def softmax_forward_zig_model (input : List Real) : ZigResult (List Real) :=
  match Nat.beq input.length 0 with
  | true => ZigResult.ok []
  | false =>
    (fun m =>
      (fun sum_exp =>
        (fun inv_sum =>
          ZigResult.ok (softmax_fwd_loop input m inv_sum)
        ) (1 / sum_exp)
      ) (sum_exp_loop input m)
    ) (list_max input)

theorem softmax_forward_correct (input : List Real)
  (h_not_empty : Nat.beq input.length 0 = false) :
  softmax_forward_zig_model input = ZigResult.ok (softmax_spec input) :=
  match_false (Nat.beq input.length 0)
    (ZigResult.ok [])
    (ZigResult.ok (softmax_spec input))
    h_not_empty
